(window.TNQ=window.TNQ||[]).push({"terms":{"연결재무제표":{"d":"지배기업과 종속기업을 하나의 경제적 실체로 보고 작성하는 재무제표로 국제회계기준의 기본재무제표입니다.","r":["개별재무제표"]},"개별재무제표":{"d":"한 회사만을 대상으로 작성한 재무제표입니다.","r":["연결재무제표"]},"예측가치":{"d":"재무정보가 미래 결과를 예측하는 데 쓰일 수 있는 성질로 목적적합성을 이루는 요소입니다.","r":["확인가치"]},"확인가치":{"d":"재무정보가 과거의 평가를 확인하거나 수정하게 해 주는 성질입니다.","r":["예측가치"]},"유의적인 영향력":{"d":"피투자자의 재무·영업정책 결정에 참여할 수 있는 힘으로 의결권 일정 비율 이상을 가지면 있다고 봅니다.","r":["지분법이익"]},"지분법이익":{"d":"관계기업 당기순이익 중 투자회사의 지분에 해당하는 금액으로 투자회사의 이익으로 보고됩니다.","r":["유의적인 영향력"]},"상각후원가":{"d":"금융자산·부채를 유효이자율법으로 상각하여 측정한 금액으로 원리금만 받는 채무증권에 적용합니다.","r":["유효이자율법"]},"위험회피수단":{"d":"회피대상 위험에서 생기는 변동을 상쇄하려고 지정한 파생상품 같은 수단입니다.","r":[]},"순실현가능가치":{"d":"정상 영업과정에서 예상되는 판매가격에서 추정 완성원가와 판매비용을 뺀 금액입니다.","r":[]},"계속기록법":{"d":"입고와 출고를 계속 기록해 장부상 재고잔량을 기말재고수량으로 삼는 방법입니다.","r":[]},"이동평균법":{"d":"매입할 때마다 평균단가를 새로 계산해 재고를 평가하는 방법입니다.","r":["가중평균법"]},"가중평균법":{"d":"총원가를 총수량으로 나눈 평균단가로 재고를 평가하는 방법입니다.","r":["이동평균법"]},"재평가잉여금":{"d":"유형자산을 재평가해 장부금액이 늘어난 금액으로 자본의 기타포괄손익누계액에 가산합니다.","r":[]},"정액법":{"d":"자산의 상각 대상 금액을 내용연수 동안 매년 같은 금액으로 나누어 비용 처리하는 방법입니다.","r":[]},"적격자산":{"d":"의도한 용도로 쓰거나 팔 수 있게 되기까지 상당한 기간이 걸리는 자산으로 차입원가를 자본화합니다.","r":[]},"유효이자율법":{"d":"금융상품의 장부금액에 유효이자율을 곱해 이자비용이나 수익을 배분하는 상각 방법입니다.","r":["상각후원가"]},"무상증자":{"d":"대가 없이 주주에게 새 주식을 나누어 주어 자본금을 늘리는 증자로 주식수 조정 때 기초에 한 것으로 봅니다.","r":[]},"수행의무":{"d":"고객에게 구별되는 재화나 용역을 이전하겠다는 계약상 약속으로 이행 시 수익을 인식합니다.","r":[]},"일시적차이":{"d":"자산·부채의 회계상 장부금액과 세무상 금액의 차이로 미래 과세소득에 영향을 줍니다.","r":["이연법인세자산","이연법인세부채"]},"이연법인세자산":{"d":"차감할 일시적차이 등으로 미래에 법인세를 줄여 줄 것으로 기대되는 금액입니다.","r":["이연법인세부채"]},"이연법인세부채":{"d":"가산할 일시적차이 때문에 미래에 추가로 내야 할 것으로 보는 법인세입니다.","r":["이연법인세자산"]},"간접법":{"d":"당기순이익에서 현금유출이 없는 비용과 자산·부채 변동 등을 조정해 영업활동 현금흐름을 구하는 방법입니다.","r":["직접법"]},"직접법":{"d":"현금을 받고 낸 항목별 총액을 그대로 보여 주어 영업활동 현금흐름을 나타내는 방법입니다.","r":["간접법"]},"현금성자산":{"d":"큰 거래비용 없이 현금으로 바꿀 수 있고 가치 변동 위험이 작은 단기 투자자산입니다.","r":[]},"기타포괄손익":{"d":"당기순손익에 넣지 않고 자본의 별도 항목으로 보고하는 손익입니다.","r":[]},"내용연수":{"d":"자산이 사용될 것으로 예상되는 기간입니다.","r":["정액법"]},"영업권":{"d":"개별적으로 식별할 수 없는 자산에서 나오는 미래 경제적 효익을 나타내는 항목입니다.","r":[]}},"notes":{"1월 1일부터 9월 30일까지의 누적기간":"누적기간 분은 연초인 1월 1일부터 9월 30일까지를 합한 기간입니다.","가중평균법으로 재고자산을 평가하고자 할 때 계속기록법에 따라 장부를 기록하는 경우에는 이동평균법을 적용하여야 한다":"계속기록법 장부에 가중평균법을 쓰면 매번 단가를 새로 구하는 이동평균법이 됩니다.","각국의 협업을 통해 제정된 회계기준이다":"한 나라가 아니라 여러 나라가 협력해 만든 공통의 회계기준입니다.","개별재무제표가 아닌 연결재무제표를 기본재무제표로 제시하고 있다":"국제회계기준에서는 지배기업과 종속기업을 묶은 연결재무제표를 기본으로 제시합니다.","거래당사자에게 금융자산을 발생시키고 동시에 거래상대방에게 금융부채나 지분상품을 발생시키는 모든 계약":"금융상품은 한쪽엔 금융자산, 다른 쪽엔 금융부채나 지분상품을 만드는 모든 계약입니다.","계약상 현금흐름이 원리금으로만 구성되고 사업모형이 계약상 현금흐름 수취인 경우 상각후원가 측정 금융자산으로 분류한다":"현금흐름이 원리금뿐이고 사업모형도 현금흐름 수취라면 상각후원가로 측정합니다.","고객에게 약속한 재화나 용역을 이전하여 수행의무를 이행할 때, 즉 고객이 자산을 통제할 때 수익을 인식한다":"수익은 고객이 자산을 통제하게 되는 때, 곧 수행의무를 이행할 때 인식합니다.","고객의 매입의사표시가 제품 등에 대한 통제의 이전으로 보아 고객이 매입의사를 표시한 시점에 수익을 인식한다":"시용판매는 고객이 매입 의사를 표시한 때 통제가 넘어갔다고 보아 그 시점에 수익을 인식합니다.","공정가치모형 적용시 감가상각은 하지 않는다":"공정가치모형을 쓰면 감가상각을 하지 않습니다.","공정가치모형 적용시 공정가치 변동으로 발생하는 손익은 당기손익에 반영한다":"공정가치가 변해서 생긴 손익은 당기손익에 바로 반영합니다.","공정가치 유상증자로 발행된 보통주와 무상증자로 발행된 보통주로 구분한다":"시가보다 낮은 유상증자는 시가분 유상증자와 무상증자분으로 나눠 봅니다.","공정가치의 적용이 확대되었다":"국제회계기준을 도입하면서 시가에 가까운 공정가치로 재는 항목이 더 많아졌습니다.","과거에 사건이나 거래가 발생하여 현재의무가 존재하여야 한다":"과거 사건으로 현재의무가 존재해야 충당부채로 인식합니다.","관계기업으로부터 수취한 배당금은 관계기업투자주식에서 직접 차감한다":"받은 배당금은 수익으로 잡지 않고 관계기업투자주식에서 곧바로 뺍니다.","관계기업의 당기순이익 중 투자회사의 지분에 해당하는 금액은 투자회사의 지분법이익으로 보고된다":"관계기업 순이익 가운데 내 지분율만큼이 지분법이익으로 보고됩니다.","구별되는 재화나 용역은 수행의무에 해당한다":"구별되는 재화나 용역 하나하나가 수행의무입니다.","금융부채는 원칙적으로 최초 인식시 공정가치로 인식한다":"금융부채는 처음 인식할 때 공정가치로 재는 것이 원칙입니다.","금융자산과 단기간 내에 제조되거나 다른 방법으로 생산되는 재고자산은 적격자산에 해당하지 아니한다":"금융자산과 짧은 기간에 만들어지는 재고자산은 적격자산이 아닙니다.","기업에 자원을 제공하는 것에 대한 의사결정을 할 때 유용한":"일반목적재무보고는 기업에 자원을 줄지 결정하는 사람에게 도움이 되도록 쓰입니다.","기업은 보상원가를 부여일에 전액 인식하고 그에 상응하여 자본의 증가를 인식한다":"바로 가득되면 부여일에 보상원가를 전액 인식하고 자본이 늘어납니다.","기업의 경영활동에 따른 현금흐름을 영업활동·투자활동·재무활동으로 구분한다":"현금흐름은 영업·투자·재무활동 세 가지로 나누어 보고합니다.","기업의 현금흐름을 나타내는 재무제표로서 현금의 변동내용을 명확하게 보고하기 위하여 당해 회계기간에 속하는 현금의 유입과 유출내용을 적정하게 표시하는 보고서":"현금흐름표는 한 회계기간의 현금 유입과 유출을 적정하게 보여 주는 보고서입니다.","기업이 고객에게 재화가 이전되기 전에 해당 재화에 대한 통제권을 가지지 않는 경우에는 대리인에 해당하기 때문에 판매가액 총액을 수익으로 계상할 수 없으며, 받을 권리를 가지는 판매수수료만을 수익으로 인식해야 한다":"통제권이 없으면 대리인이므로 판매가 총액이 아니라 받을 몫만 수익입니다.","기업이 재화나 용역을 제공받는 대가로 기업의 지분상품을 부여하는 것이다":"주식결제형은 용역을 받는 대가로 회사의 지분상품을 주는 보상입니다.","기업이 재화나 용역을 제공받는 대가로 기업의 지분상품의 가치에 기초하여 현금 등을 지급하는 것이다":"현금결제형은 지분상품 가치에 연동해 현금 등을 지급하는 보상입니다.","기존 건물 철거로 발생한 폐자재들을 처리하는 비용이 발생하는 경우 토지의 원가에 가산한다":"낡은 건물을 헐고 나온 폐자재의 처리비도 토지 원가에 보탭니다.","기타포괄손익-공정가치 측정 금융자산으로 분류할 수 없다":"단기매매 목적이면 기타포괄손익-공정가치 측정 쪽으로는 분류할 수 없습니다.","나타내고자 하는 현상의 실질을 충실하게 표현해야 한다":"표현충실성은 겉모양이 아니라 현상의 실질을 그대로 담아야 한다는 성질입니다.","내부적으로 창출한 영업권은 무형자산으로 인식할 수 없다":"스스로 만들어 낸 영업권은 무형자산으로 올릴 수 없습니다.","내부 프로젝트에서 발생한 원가 중 연구단계에서 발생한 원가는 무형자산으로 인식할 수 없다":"연구단계에서 쓴 원가는 무형자산으로 올릴 수 없습니다.","내용연수가 비한정인 무형자산이 내용연수 검토결과 더 이상 비한정이라는 평가를 정당화할 수 없다면 내용연수가 유한한 무형자산으로 변경해야 한다":"검토 결과 비한정이라고 보기 어려워지면 유한한 내용연수의 무형자산으로 바꿔야 합니다.","당기 중 보통주가 발행된 경우 기초에 실시된 것으로 간주하여 주식수를 조정한다":"무상증자는 기초에 한 것처럼 간주해 주식수를 조정합니다.","당해 사채의 액면금액에 부가하는 형식으로 기재한다":"할증발행차금은 액면금액에 더하는 형식으로 적습니다.","당해 자산이 폐기되거나 제거될 때에는 자본(기타포괄손익누계액)에 계상된 재평가잉여금을 이익잉여금으로 대체할 수 있다":"자산이 폐기·제거될 때는 쌓인 재평가잉여금을 이익잉여금으로 옮길 수 있습니다.","당해 주식의 납입일을 기준일로 하여 가중평균유통주식수를 계산한다":"시가대로 유상증자하면 납입일부터 유통된 기간만큼만 가중평균에 반영됩니다.","당 회계연도 1월 1일부터 9월 30일까지의 누적기간":"자본변동표는 중간기간 단위가 아니라 1월 1일부터 9월 30일까지 누적기간 하나로 만듭니다.","당 회계연도 7월 1일부터 9월 30일까지의 중간기간과":"중간기간 분 포괄손익계산서는 7월 1일부터 9월 30일까지를 대상으로 삼습니다.","동 교환거래에 상업적 실질이 결여되어 있다면, 취득한 무형자산의 원가는 제공한 자산의 장부금액으로 한다":"상업적 실질이 없는 교환이면 새로 얻은 무형자산의 원가는 준 자산의 장부금액입니다.","매입원가, 전환원가 및 재고자산을 현재의 장소에 현재의 상태로 이르게 하는 데 발생한 기타원가 모두를 포함한다":"취득원가는 매입원가와 전환원가에 현재 장소·상태에 이르게 한 기타원가까지 모두 합칩니다.","매입할인, 리베이트 및 기타 유사한 항목은 매입원가를 결정할 때 차감한다":"받은 매입할인과 리베이트는 매입원가를 정할 때 뺍니다.","무형자산 원가의 인식은 그 자산을 경영자가 의도하는 방식으로 운용될 수 있는 상태에 이르면 중지한다":"경영자가 의도한 방식으로 운용할 수 있는 상태가 되면 원가 인식을 멈춥니다.","발생하는 경우 취득한 기간의 당기손익에 포함한다":"염가매수차익이 생기면 취득한 기간의 당기손익에 넣습니다.","발생한 지출은 무형자산 인식조건을 모두 충족하는 경우에만 무형자산으로 인식한다":"개발단계의 지출은 인식조건을 모두 충족해야만 무형자산이 됩니다.","보고기업의 재무정보를 제공하는 것이다":"그 목적을 위해 보고기업의 재무정보를 제공합니다.","보상원가를 용역제공 기간에 배분하여 인식한다":"일정 기간 일해야 가득되면 그 기간에 걸쳐 보상원가를 나눠 인식합니다.","보유현금과 요구불예금 및 현금성자산을 말한다":"현금및현금성자산에는 보유현금, 요구불예금, 현금성자산이 들어갑니다.","보증을 별도의 수행의무로 보아 거래가격의 일부를 배분한다":"용역 유형의 보증은 별도 수행의무로 보아 거래가격 일부를 배분합니다.","사채의 발행금액에서 차감한다":"사채발행비는 발행금액에서 빼서 계상합니다.","사채의 상환손익이 발생하는 이유는 상환일의 시장이자율이 발행일의 시장이자율과 다르기 때문이다":"상환일 시장이자율이 발행일과 다르기 때문에 상환손익이 생깁니다.","상법의 규정에 의하여 주식회사가 강제적으로 기업내부에 유보하여야 하는 법정적립금이다":"이익준비금은 상법 때문에 회사가 반드시 쌓아 두어야 하는 법정적립금입니다.","서술은 완전하고, 중립적이며, 오류가 없어야 한다":"충실한 서술은 빠짐없고, 한쪽으로 기울지 않고, 오류가 없어야 합니다.","수취 및 지급에 따른 현금흐름은 각각 별도로 공시한다":"이자와 배당금의 수취와 지급은 각각 따로 공시해야 합니다.","신주발행 없이 자기주식을 교부할 수 있다":"권리를 행사할 때 새 주식을 내는 대신 자기주식을 줄 수도 있습니다.","신주발행을 위하여 직접 발생한 비용은 주식발행금액에서 직접 차감한다":"신주발행에 직접 든 비용은 주식발행금액에서 바로 뺍니다.","실지재고조사를 통해 기말재고수량을 파악한다":"실지재고조사법은 기말에 직접 세어 재고 수량을 파악합니다.","영업활동에 관한 정보뿐만 아니라 투자활동 및 재무활동에 관한 정보도 제공한다":"영업활동뿐 아니라 투자와 재무활동에 관한 정보도 이 표에서 얻습니다.","영업활동 현금흐름 또는 재무활동 현금흐름":"이자지급과 배당금지급은 영업활동이나 재무활동으로 분류합니다.","영업활동 현금흐름 또는 투자활동 현금흐름":"이자수입과 배당금수입은 영업활동이나 투자활동으로 분류합니다.","영업활동 현금흐름을 어떻게 계산하느냐에 따라 간접법과 직접법으로 구분된다":"영업활동 현금흐름을 어떤 방식으로 계산하느냐에 따라 간접법과 직접법이 갈립니다.","원가모형과 재평가모형 중 하나를 회계정책으로 선택하여 유형자산의 유형별로 동일하게 적용하여야 한다":"원가모형과 재평가모형 중 하나를 정책으로 골라 유형자산의 같은 유형에는 똑같이 적용합니다.","원칙적으로 그 증가액은 기타포괄이익으로 인식하고 재평가잉여금의 과목으로 자본(기타포괄손익누계액)에 가산한다":"재평가로 늘어난 금액은 원칙적으로 기타포괄이익이며 자본의 재평가잉여금으로 쌓입니다.","위험회피수단에 대한 손익 중 위험회피에 효과적인 부분은 당해 회계연도에 기타포괄손익으로 인식한다":"위험회피에 효과적인 부분은 그 회계연도에 기타포괄손익으로 먼저 인식합니다.","유가증권 소유자가 일정한 조건하에 보통주로의 전환권을 행사할 수 있는 사채로서, 전환권을 행사하면 보통주로 전환되는 사채":"전환사채는 전환권을 행사하면 사채가 보통주로 바뀝니다.","유가증권의 소유자가 일정한 조건하에 신주인수권을 행사하여 보통주 발행을 청구할 수 있는 권리가 부여된 사채":"신주인수권부사채는 신주인수권으로 보통주 발행을 청구할 수 있는 사채입니다.","유가증권의 소유자가 일정한 조건하에 전환권을 행사할 수 있는 우선주로서, 전환권을 행사하면 보통주로 전환되는 우선주":"전환우선주는 조건에 따라 전환권을 행사하면 보통주가 되는 우선주입니다.","유형자산의 원가에 포함시켜야 한다":"그런 경우 이 추정비용은 유형자산 원가에 포함시켜야 합니다.","유효이자율법에 따른 이자비용을 인식한다":"상각후원가 측정 금융부채는 유효이자율법으로 계산한 이자비용을 인식합니다.","유효이자율법을 적용하여 상각하고 상각액을 사채이자에 가산한다":"할인발행차금은 유효이자율법으로 상각하고 그 액수를 이자 쪽에 더합니다.","의사결정에 차이가 나도록 할 수 있다":"그런 가치를 가진 재무정보는 이용자의 의사결정을 바꿀 수 있습니다.","이연법인세부채를 발생시킬 수 있다":"가산할 일시적차이는 이연법인세부채를 낳을 수 있습니다.","이연법인세자산·부채는 일시적 차이의 소멸시기와 관계없이 비유동항목으로 구분하여 재무상태표에 표시한다":"소멸 시기와 상관없이 이연법인세자산·부채는 비유동항목으로 표시합니다.","이연법인세자산을 발생시킬 수 있다":"차감할 일시적차이는 이연법인세자산을 낳을 수 있습니다.","일괄구입대가를 개별자산의 공정가치비율로 안분하여 토지와 건물의 원가를 산정한다":"토지와 건물을 다 쓸 때는 총대가를 각 자산의 공정가치 비율로 나눠 원가를 정합니다.","일괄구입대가 모두 토지의 취득원가로 처리한다":"토지만 쓸 목적이면 건물 몫까지 모두 토지 취득원가가 됩니다.","일반적으로 당기손익-공정가치 측정 금융자산으로 분류한다":"지분증권은 따로 선택하지 않으면 공정가치 변동이 당기손익에 반영되는 자산으로 분류합니다.","일반적으로 미처분이익잉여금에서 출발하여 임의적립금 등의 이입액을 더하고, 이익잉여금처분액을 차감하여 차기이월미처분이익잉여금을 구하는 방식으로 작성된다":"미처분이익잉여금에서 시작해 임의적립금 이입액을 더하고 처분액을 빼서 차기이월액을 구합니다.","일반적인 신용기간보다 긴 경우 무형자산의 원가는 현금가격상당액으로 한다":"대금 지급 기간이 일반 신용기간보다 길면 원가는 현금으로 샀을 때의 가격입니다.","일시적차이가 소멸될 것으로 예상되는 기간의 과세소득에 적용될 것으로 기대되는 평균세율을 적용하여 이연법인세자산·부채를 측정한다":"이연법인세는 일시적차이가 없어질 시기의 과세소득에 적용될 평균세율로 측정합니다.","임대수익이나 시세차익 또는 두 가지 모두를 얻기 위하여 소유자가 보유하거나 리스이용자가 사용권자산으로 보유하고 있는 부동산":"투자부동산은 임대료나 시세차익을 노리고 가진 부동산을 말합니다.","자산을 의도된 용도로 사용(또는 판매) 가능하게 하기 위한 과정에 있어 일시적인 지연이 필수적인 경우에는 자본화를 중단하지 아니한다":"과정에 꼭 필요한 일시적 지연이라면 차입원가 자본화를 멈추지 않습니다.","자산의 경제적 효익이 소비되는 형태를 반영해야 하며, 소비되는 형태를 신뢰성 있게 결정할 수 없는 경우에는 정액법을 사용한다":"소비 형태를 반영해 상각하되 그것을 믿을 만하게 정할 수 없으면 정액법을 씁니다.","자산취득 관련 정부보조금은 관련 자산의 장부금액에서 차감하는 방법과 이연수익(부채)으로 표시하는 방법 중 한 가지 방법을 선택하여 처리할 수 있다":"자산 관련 정부보조금은 장부금액에서 빼거나 이연수익(부채)으로 표시하는 두 방법 중 하나를 고릅니다.","장부상의 재고잔량을 기말재고수량으로 결정한다":"계속기록법은 입출고를 계속 적어 장부상 남은 수량을 기말재고수량으로 삼습니다.","재고자산은 취득원가와 순실현가능가치 중 낮은 금액으로 측정한다":"재고는 취득원가와 순실현가능가치를 견줘 더 낮은 쪽으로 측정합니다.","재고자산의 취득원가에 포함하지 않는다":"판매에 드는 원가는 재고자산의 취득원가에서 제외됩니다.","재고장에 입고기록만 할 뿐, 출고기록은 수행하지 않는다":"입고만 적고 출고를 적지 않으니, 나간 수량은 기말 실사 결과를 기준으로 알게 됩니다.","재무정보에 예측가치, 확인가치 또는 이 둘 모두가 있다면":"예측가치나 확인가치 중 하나라도 있는 정보는 이용자의 판단에 영향을 줄 수 있습니다.","재무활동과 투자활동에 명백히 관련되지 않는 한 영업활동 현금흐름":"법인세 현금흐름은 재무·투자활동과 분명히 관련되지 않으면 영업활동으로 봅니다.","재화나 용역을 이전하는 시점과 고객이 대가를 지급하는 시점이 1년 이내로 예상되는 경우 금융요소가 유의적이지 않다고 보아 계약에 있는 금융요소를 조정하지 않을 수 있다":"대가 지급 시점과 이전 시점의 차이가 1년 이내로 예상되면 금융요소가 유의적이지 않다고 보아 조정하지 않을 수 있습니다.","적격자산을 의도된 용도로 사용(또는 판매) 가능하게 하는 데 필요한 대부분의 활동이 완료된 시점에 자본화를 종료한다":"사용·판매 가능하게 하는 활동 대부분이 끝난 시점에 자본화도 끝냅니다.","적용할 때 기말재고금액이 높게 계상된다":"선입선출법에서는 기말재고에 상대적으로 큰 금액이 계상됩니다.","정보이용자의 의사결정에 차이가 나도록 할 수 있다":"목적적합성은 정보가 이용자의 결정을 달라지게 할 힘이 있다는 성질입니다.","종업원으로부터 용역을 제공받는 경우 보상원가 산정시 지분상품의 공정가치는 부여일 현재로 측정하고 이후에 공정가치가 변동되는 경우에도 변동분을 반영하지 않는다":"종업원 보상원가는 부여일 공정가치로 재고, 나중에 가치가 변해도 반영하지 않습니다.","지출하는 시기 또는 금액이 불확실한 부채를 말한다":"충당부채는 갚을 시기나 금액이 확정되지 않은 부채입니다.","직전 회계연도의 동일 기간을 대상으로 작성한 자본변동표":"자본변동표도 직전 회계연도의 같은 누적기간 것과 견주게 합니다.","직전 회계연도의 동일 기간을 대상으로 작성한 포괄손익계산서":"비교하도록 전년도의 같은 기간 것도 함께 만듭니다.","직전 회계연도의 동일 기간을 대상으로 작성한 현금흐름표":"현금흐름표 역시 직전 회계연도의 같은 기간 것이 비교 대상입니다.","취득세, 등록세 등 취득부대원가를 가산한 금액을 취득원가로 한다":"토지 원가는 매입대금에 취득세·등록세 같은 부대원가를 더한 금액입니다.","투자자가 직접 또는 간접으로 피투자자에 대한 의결권의 20% 이상을 소유하고 있다면 명백한 반증이 없는 한 유의적인 영향력이 있는 것으로 본다":"의결권의 20% 이상을 가지면 반증이 없는 한 유의적 영향력이 있다고 보아 관계기업으로 다룹니다.","투자자의 보고기간종료일과 관계기업의 보고기간종료일이 다른 경우, 실무적으로 적용할 수 없는 경우가 아니면 관계기업은 투자자의 재무제표와 동일한 보고기간종료일의 재무제표를 작성한다":"결산일이 다르더라도 가능하면 관계기업도 투자자와 같은 결산일 기준으로 재무제표를 만들어야 합니다.","투자회사가 수취하는 배당금 금액은 관계기업투자주식의 장부금액을 감소시킨다":"배당을 받을수록 관계기업투자주식의 장부금액이 줄어듭니다.","특정한 고객을 위한 비제조간접원가 또는 제품디자인원가는 재고자산의 원가에 포함하는 것이 적절할 수도 있다":"특정 고객용 비제조간접원가나 제품디자인원가는 경우에 따라 재고 원가에 넣는 편이 맞습니다.","해당 유형자산의 경제적 사용이 종료된 후에 원상회복을 위하여 그 자산을 제거, 해체하거나 또는 부지를 복원하는데 소요될 것으로 추정되는 비용이 부채의 인식요건을 충족하는 경우 그 지출의 현재가치":"사용을 마친 뒤 해체하거나 부지를 복원하는 데 들 추정비용이 부채 인식요건을 채우는 경우입니다.","현재 및 잠재적인 투자자, 대여자와 그 밖의 채권자":"주요 이용자는 현재·잠재 투자자와 대여자, 그 밖의 채권자입니다.","화폐의 시간가치가 중요한 경우에도 이연법인세자산·부채는 현재가치로 평가하지 않는다":"시간가치가 중요해도 이연법인세자산·부채는 현재가치로 할인하지 않습니다.","화폐의 시간가치 영향이 중요한 경우에는 의무를 이행하기 위하여 예상되는 지출액의 현재가치로 평가한다":"시간가치 영향이 크면 예상 지출액을 현재가치로 바꿔 평가합니다.","후속 생산단계에 투입하기 전에 보관이 필요한 경우에 발생하는 보관원가는 취득원가에 포함한다":"다음 생산단계에 넣기 전 꼭 보관해야 해서 드는 보관원가는 취득원가에 들어갑니다.","후속 생산단계에 투입하기 전에 보관이 필요한 경우 이외에 발생하는 보관원가는 취득원가에 포함할 수 없으며 발생한 기간의 비용으로 인식한다":"그 밖의 보관원가는 취득원가에 넣을 수 없고 발생한 기간의 비용입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
